import csv, collections, statistics as st

ids = {
 'F3_Z01_s':'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
 'F3_Z02_s':'bcc5a78f-36a4-55a0-9420-7a80fc9b2deb',
 'F3_Z03_s':'9c6223f8-3611-5ceb-9107-70e8206e9ccd',
 'F3_Z05_s':'c49bbc2f-096e-5e16-bead-066250790308',
 'F3_Z01_dsp':'6275dc72-6fab-5140-8635-c0fe7ed3894d',
 'F3_Z02_dsp':'c8335f0f-a2b5-564c-a458-e240e9716029',
 'F3_Z03_dsp':'147004e7-33ef-553b-8135-d40d8b765bb5',
 'F3_Z05_dsp':'bebab0bb-2daa-57a2-abeb-ddb23449e7a7',
}
data=collections.defaultdict(list)
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row['timeseries_id'] in ids:
            data[row['timeseries_id']].append((row['timestamp'], float(row['value'])))
for k,v in data.items(): v.sort()

def avg(k, start, end):
    v=[val for ts,val in data[k] if start<=ts<end]
    return sum(v)/len(v) if v else None, len(v)

periods=[('pre-Jul18','2018-01-01','2018-07-01'),('Jul18-19','2018-07-01','2019-01-01'),('Jul19-20','2019-07-01','2020-01-01')]
print('time range overall:', data['F3_Z01_s'][0][0], data['F3_Z01_s'][-1][0])
for k in ids:
    row=[]
    for label,s,e in periods:
        a,n=avg(k,s,e)
        row.append(f"{label}={a if a is None else round(a,2)}(n={n})")
    print(f"{k:10s}", " ".join(row))

print()
for k in ['F3_Z01_s','F3_Z02_s','F3_Z03_s','F3_Z05_s']:
    vals=[v for _,v in data[k]]
    print(k,'min',min(vals),'max',max(vals),'mean',round(sum(vals)/len(vals),2))
for k in ['F3_Z01_dsp','F3_Z02_dsp','F3_Z03_dsp','F3_Z05_dsp']:
    vals=[v for _,v in data[k]]
    print(k,'min',min(vals),'max',max(vals),'mean',round(sum(vals)/len(vals),2))
